501	// ---------------------------------------------------------------------------
502	// In-guest disk usage via the QEMU guest agent (get-fsinfo)
503	// ---------------------------------------------------------------------------
504	
505	/** Real filesystem usage as reported from *inside* the guest. */
506	export type GuestDiskUsage = { usedBytes: number; totalBytes: number };
507	
508	/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
509	export type GuestAgentClient = {
510	  get: (path: string, params?: Record<string, any>) => Promise<any>;
511	};
512	
513	// Pseudo / virtual filesystems that don't represent real on-disk usage and must
514	// never be picked as the root filesystem. Matched against the fsinfo `type`.
515	const PSEUDO_FS_TYPES = new Set([
516	  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
517	  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
518	  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
519	  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
520	]);
521	
522	/** Is this mountpoint one we should ignore even if the type looks real? */
523	function isIgnorableMount(mountpoint: string): boolean {
524	  const mp = String(mountpoint ?? "");
525	  return (
526	    mp === "/boot" ||
527	    mp.startsWith("/boot/") ||
528	    mp.startsWith("/snap") ||
529	    mp.startsWith("/var/lib/docker") ||
530	    mp.startsWith("/run") ||
531	    mp.startsWith("/dev") ||
532	    mp.startsWith("/sys") ||
