537	/**
538	 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
539	 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
540	 *
541	 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
542	 * in-guest usage — so this agent call is the only source of real used/total
543	 * bytes. Best-effort: returns null on any error or when the agent isn't ready
544	 * (never throws), so a missing agent degrades cleanly to the provisioned-size
545	 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
546	 *
547	 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
548	 */
549	export async function getGuestDiskUsage(
550	  client: GuestAgentClient,
551	  node: string,
552	  vmid: number,
553	  sandboxTotalBytes?: number
554	): Promise<GuestDiskUsage | null> {
555	  if (SANDBOX) {
556	    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
557	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
558	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
559	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
560	    return { usedBytes: Math.round(total * frac), totalBytes: total };
561	  }
562	
563	  try {
564	    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
565	    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
566	    const list: any[] = Array.isArray(res?.result)
567	      ? res.result
568	      : Array.isArray(res)
569	        ? res
570	        : [];
571	    if (list.length === 0) return null;
572	
573	    const real = list.filter((fs) => {
574	      const type = String(fs?.type ?? "").toLowerCase();
575	      const mp = String(fs?.mountpoint ?? "");
576	      if (PSEUDO_FS_TYPES.has(type)) return false;
577	      if (isIgnorableMount(mp)) return false;
578	      const total = Number(fs?.["total-bytes"]);
579	      return Number.isFinite(total) && total > 0;
580	    });
581	    if (real.length === 0) return null;
582	
583	    // Prefer the real root filesystem; otherwise the largest real mount.
584	    const root =
585	      real.find((fs) => String(fs?.mountpoint) === "/") ??
586	      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];
587	
588	    const usedBytes = Number(root?.["used-bytes"]);
589	    const totalBytes = Number(root?.["total-bytes"]);
590	    if (!Number.isFinite(usedBytes) || !Number.isFinite(totalBytes) || totalBytes <= 0) {
591	      return null;
592	    }
593	    return { usedBytes, totalBytes };
594	  } catch {
595	    // Agent not installed / not ready / VM stopped / transient PVE error.
596	    return null;
597	  }
598	}
