600	/**
601	 * Wait until the QEMU guest agent answers, i.e. until the guest has genuinely
602	 * booted far enough to run software.
603	 *
604	 * WHY: `waitForTask(startUpid)` proves only that Proxmox ACCEPTED the start —
605	 * not that the guest booted, that cloud-init ran, or that sshd is listening. The
606	 * provision path used to write RUNNING and hand the customer a copy-pasteable
607	 * `ssh root@…` line on the strength of that task alone (M7 #10), which is why a
608	 * RUNNING server eight minutes old could still show "SSH command: provisioning…".
609	 *
610	 * Returns true only on a real reply. On timeout it returns FALSE rather than
611	 * throwing, so the caller can degrade its message honestly instead of failing a
612	 * server that is merely slow — a guest with no agent installed is a normal state
613	 * for some images, and calling that a provisioning failure would be its own lie.
614	 */
615	export async function waitForGuestAgent(
616	  client: GuestAgentClient,
617	  node: string,
618	  vmid: number,
619	  timeoutMs = 180_000,
620	  pollMs = 5_000
621	): Promise<boolean> {
622	  const deadline = Date.now() + timeoutMs;
623	  for (;;) {
624	    try {
625	      await client.get(`/nodes/${node}/qemu/${vmid}/agent/ping`);
626	      return true;
627	    } catch {
628	      /* agent not up yet */
629	    }
630	    if (Date.now() >= deadline) return false;
631	    await new Promise((r) => setTimeout(r, pollMs));
632	  }
633	}
