665	// ---------------------------------------------------------------------------
666	// Platform backups vs customer backups
667	// ---------------------------------------------------------------------------
668	//
669	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
670	// used to write the platform's own host-level disaster-recovery archives into the
671	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
672	// backups land in, and `pruneBackups` below selected victims with nothing but
673	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
674	// archives — the customer's own manual one from 2026-07-25 12:22 and the
675	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
676	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
677	// the platform's copy of their VM. Repeated across the fleet that silently
678	// destroys the entire bare-metal recovery set, one customer click at a time.
679	//
680	// The fix is three independent layers, in order of strength:
681	//
682	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
683	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
684	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
685	//     platform archives have no `volid` at all: they cannot appear in the
686	//     `/storage/backup/content` listing this function iterates, and there is no
687	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
688	//     them. Not "filtered out" — not addressable.
689	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
690	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
691	//     worker/index.ts). It re-derives protection for every volid immediately
692	//     before deleting and refuses on any of: the PVE `protected` attribute, the
693	//     platform notes marker, or the protection registry — and it fails CLOSED if
694	//     it cannot determine the answer.
695	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
696	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
697	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
698	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
699	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
700	//     before layer 1 existed.
701	
702	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
703	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
704	
705	/**
706	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
707	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
708	 * notes contain this string.
709	 */
710	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
711	
712	/**
713	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
714	 * pre-existing platform archives that were written into the shared storage before
715	 * the dumpdir split. Anything listed here is undeletable through this module.
716	 */
717	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
718	
719	/**
720	 * Read the protection registry.
721	 *
722	 * Returns `null` when the registry exists but could not be read. Callers MUST
723	 * treat `null` as "protection state unknown" and refuse to delete: a transient
724	 * EIO on this file must not be the thing that lets a customer's prune wipe the
725	 * platform's recovery set. A registry that simply does not exist yet (fresh
726	 * install, platform job has never run) is a legitimate empty set — layer 1 means
727	 * there is nothing in the shared storage to protect in that case anyway.
728	 */
729	async function protectedVolids(): Promise<Set<string> | null> {
730	  const { readFile } = await import("node:fs/promises");
731	  try {
732	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
733	    return new Set(
734	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
735	    );
736	  } catch (e: any) {
737	    if (e?.code === "ENOENT") return new Set();
738	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
739	    return null;
740	  }
741	}
742	
743	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
744	/**
745	 * Every backup archive the `backup` storage holds for one VMID, read through a
746	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
747	 * archive actually exists: the vzdump task's exit status says the task ran, not
748	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
749	 * incident H4.
750	 */
751	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
752	  const content: StorageBackupEntry[] = await client.get(
753	    `/nodes/${client.node}/storage/backup/content`,
754	    { content: "backup" }
755	  );
756	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
757	}
