759	export type StorageBackupEntry = {
760	  volid?: string;
761	  vmid?: number;
762	  ctime?: number;
763	  size?: number;
764	  notes?: string;
765	  protected?: boolean | number;
766	};
767	
768	/**
769	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
770	 * Any single signal is enough — they are deliberately redundant.
771	 */
772	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
773	  if (b.protected) return true;
774	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
775	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
776	  return false;
777	}
