779	/**
780	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
781	 *
782	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
783	 * "a customer can never delete a platform archive" invariant is enforced rather
784	 * than merely intended. It re-checks protection against the live hypervisor for
785	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
786	 * volid cannot slip past it. Every uncertain outcome throws.
787	 */
788	export async function deleteBackup(client: any, volid: string): Promise<void> {
789	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
790	  // anything else keeps a malformed or path-traversing volid from ever reaching
791	  // the API, and keeps this function honest about what it operates on.
792	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
793	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
794	
795	  const registry = await protectedVolids();
796	  if (registry === null) {
797	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
798	  }
799	  if (registry.has(volid)) {
800	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
801	  }
802	
803	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
804	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
805	  // here means we do not know whether this is a platform archive, so we stop.
806	  let info: any;
807	  try {
808	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
809	  } catch (e) {
810	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
811	  }
812	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
813	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
814	  }
815	
816	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
817	}
818	
819	/**
820	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
821	 * belong to that customer, deleting the older ones (best-effort per file, oldest
822	 * first). Runs after every successful customer backup, and from the standalone
823	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
824	 *
825	 * Platform archives are excluded from the delete set AND from the retention
826	 * count. Counting them would be its own bug: with keep = 2, three platform
827	 * archives of a vmid would make every customer archive "older than the newest
828	 * two" and delete all of the customer's backups instead.
829	 */
830	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
831	  // `keep` decides how many of a customer's restore points survive, so it is
832	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
833	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
834	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
835	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
836	  // the way past. Fail closed instead — an over-retained archive costs disk, a
837	  // missing one costs the customer their only restore point.
838	  if (!Number.isInteger(keep) || keep < 1) {
839	    throw new Error(
840	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
841	        `retention must be a whole number of at least 1.`
842	    );
843	  }
844	
845	  const registry = await protectedVolids();
846	  if (registry === null) {
847	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
848	    // recoverable; deleting the platform's only copy of a VM is not.
849	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
850	    return 0;
851	  }
852	
853	  const forVmid = await listBackupsOn(client, vmid);
854	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
855	  const mine = forVmid
856	    .filter((b) => !isPlatformArchive(b, registry))
857	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
858	
859	  if (shielded.length > 0) {
860	    console.log(
861	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
862	    );
863	  }
864	
865	  const toDelete = mine.slice(Math.max(0, keep));
866	  let deleted = 0;
867	  for (const b of toDelete) {
868	    try {
869	      await deleteBackup(client, b.volid!);
870	      deleted++;
871	    } catch (e) {
872	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
873	    }
874	  }
875	  return deleted;
876	}
