1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { signTerminalToken } from "@/lib/terminal-token";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	
8	/**
9	 * Web-terminal authorization ticket issuer.
10	 *
11	 *   POST /api/terminal/token   { serverId }
12	 *
13	 * Flow:
14	 *  1. Authenticate the caller (reuses lib/auth `requireUser`).
15	 *  2. Verify the caller OWNS the target server (userId match — or an admin) and
16	 *     that it is RUNNING. This is the ONLY place the session cookie is checked;
17	 *     the websocket itself is authorized purely by the token minted here.
18	 *  3. Mint a 60-second encrypted token encoding { userId, serverId } and return
19	 *     it. The browser hands this token to the terminal websocket, which
20	 *     re-verifies it and re-checks ownership before SSHing to the VM.
21	 *
22	 * The token is short-lived and single-purpose: it authorizes opening ONE shell
23	 * on ONE server for the user it names. It carries no credentials — the VM's
24	 * root password never leaves the server side.
25	 */
26	export const dynamic = "force-dynamic";
27	
28	export async function POST(req: NextRequest) {
29	  let user;
30	  try {
31	    user = await requireUser();
32	  } catch {
33	    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
34	  }
35	
36	  // Throttle minting per user so a stolen session can't spin up shells in a loop.
37	  const rl = checkRateLimit(`terminal:token:${user.id}`, { max: 20, windowMs: 60_000 });
38	  if (!rl.ok) {
39	    return NextResponse.json(
40	      { error: "too many terminal requests — slow down", retryAfterSec: rl.retryAfterSec },
41	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
42	    );
43	  }
44	
45	  let serverId: unknown;
46	  try {
47	    const body = await req.json();
48	    serverId = body?.serverId;
49	  } catch {
50	    return NextResponse.json({ error: "expected a JSON body" }, { status: 400 });
51	  }
52	  if (typeof serverId !== "string" || !serverId) {
53	    return NextResponse.json({ error: "serverId is required" }, { status: 400 });
54	  }
55	
56	  // Ownership check — same pattern as lib/actions-server-ops.ts / app/api/files:
57	  // the server must exist and belong to the caller (admins may open any).
58	  const server = await db.server.findUnique({
59	    where: { id: serverId },
60	    select: { id: true, userId: true, status: true },
61	  });
62	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
63	    return NextResponse.json({ error: "not found" }, { status: 404 });
64	  }
65	  if (server.status !== "RUNNING") {
66	    return NextResponse.json(
67	      { error: "server must be running to open a terminal" },
68	      { status: 409 }
69	    );
70	  }
71	
72	  const token = await signTerminalToken({ userId: user.id, serverId: server.id });
73	  // The body IS the credential that opens a root shell on this VM — it must not
74	  // be written to any cache, shared or private.
75	  return NextResponse.json({ token }, { headers: NO_STORE_HEADERS });
76	}
