119	async function handleConnection(ws: WebSocket, req: IncomingMessage): Promise<void> {
120	  let closed = false;
121	  let idleTimer: NodeJS.Timeout | null = null;
122	  let authTimer: NodeJS.Timeout | null = null;
123	  let maxTimer: NodeJS.Timeout | null = null;
124	  let ssh: SshClient | null = null;
125	  const { agentMode, approval } = parseAgentParams(req.url);
126	
127	  /** Close everything exactly once; optionally send a final line to the client. */
128	  function shutdown(reason: string, notify?: string): void {
129	    if (closed) return;
130	    closed = true;
131	    if (idleTimer) clearInterval(idleTimer);
132	    if (authTimer) clearTimeout(authTimer);
133	    if (maxTimer) clearTimeout(maxTimer);
134	    if (notify && ws.readyState === WebSocket.OPEN) {
135	      try {
136	        ws.send(`\r\n\x1b[33m${notify}\x1b[0m\r\n`);
137	      } catch {
138	        /* ignore */
139	      }
140	    }
141	    try {
142	      ssh?.end();
143	    } catch {
144	      /* ignore */
145	    }
146	    try {
147	      if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
148	        ws.close(1000, reason.slice(0, 120));
149	      }
150	    } catch {
151	      /* ignore */
152	    }
153	  }
154	
155	  // --- Idle + max-duration guards -------------------------------------------
156	  let lastActivity = Date.now();
157	  const bump = () => {
158	    lastActivity = Date.now();
159	  };
160	  idleTimer = setInterval(() => {
161	    if (Date.now() - lastActivity > (agentMode ? AGENT_IDLE_TIMEOUT_MS : IDLE_TIMEOUT_MS)) {
162	      shutdown("idle timeout", "Session closed after 10 minutes of inactivity.");
163	    }
164	  }, 15_000);
165	  idleTimer.unref?.();
166	  maxTimer = setTimeout(() => {
167	    shutdown("max duration", "Session ended — 60 minute limit reached.");
168	  }, MAX_SESSION_MS);
169	  maxTimer.unref?.();
170	
171	  // Must authenticate + establish a shell within the auth/connect window.
172	  authTimer = setTimeout(() => {
173	    shutdown("auth/connect timeout", "Timed out establishing the terminal session.");
174	  }, AUTH_CONNECT_TIMEOUT_MS);
175	  authTimer.unref?.();
176	
177	  ws.on("error", () => shutdown("ws error"));
178	  ws.on("close", () => shutdown("ws closed"));
179	
180	  // --- Verify the token from the query string --------------------------------
181	  let claims: { userId: string; serverId: string };
182	  try {
183	    const url = new URL(req.url ?? "/", "http://localhost");
184	    const token = url.searchParams.get("token");
185	    if (!token) {
186	      shutdown("no token", "No authorization token supplied.");
187	      return;
188	    }
189	    claims = await verifyTerminalToken(token);
190	  } catch {
191	    shutdown("bad token", "Authorization token is invalid or expired.");
192	    return;
193	  }
194	  if (closed) return;
195	
196	  // --- Re-load the server and RE-CHECK ownership + RUNNING --------------------
197	  const server = await db.server.findUnique({
198	    where: { id: claims.serverId },
199	    select: {
200	      id: true,
201	      userId: true,
202	      status: true,
203	      rootPassword: true,
204	      rootPasswordEnc: true,
205	      sshPort: true,
206	      dedicatedIp: { select: { address: true } },
207	    },
208	  });
209	  if (closed) return;
210	  if (!server || server.userId !== claims.userId) {
211	    shutdown("ownership", "You do not have access to this server.");
212	    return;
213	  }
214	  if (server.status !== "RUNNING") {
215	    shutdown("not running", "Server is not running.");
216	    return;
217	  }
218	
219	  // --- SANDBOX: simulated shell, no SSH --------------------------------------
220	  if (SANDBOX) {
221	    if (authTimer) {
222	      clearTimeout(authTimer);
223	      authTimer = null;
224	    }
225	    if (agentMode) startSandboxAgent(ws, bump, shutdown);
226	    else startSandboxShell(ws, bump, shutdown);
227	    return;
228	  }
229	
230	  // --- Resolve connection target + credentials -------------------------------
231	  const target = connectionTarget(server);
232	  if (!target) {
233	    shutdown("unreachable", "Server is not reachable yet — connection details are pending.");
234	    return;
235	  }
236	  const password = serverRootPassword(server);
237	  if (!password) {
238	    shutdown("no password", "Server has no root password set.");
239	    return;
240	  }
241	
242	  // --- Open the SSH connection + request a PTY shell -------------------------
243	  ssh = new SshClient();
244	
245	  ssh.on("ready", () => {
246	    if (closed) {
247	      ssh?.end();
248	      return;
249	    }
250	    if (agentMode) {
251	      if (authTimer) { clearTimeout(authTimer); authTimer = null; }
252	      startAgentExec(ws, ssh!, approval, bump, shutdown);
253	      return;
254	    }
255	    ssh!.shell({ term: "xterm-256color", cols: 80, rows: 24 }, (err, stream) => {
256	      if (err || closed) {
257	        shutdown("shell error", "Could not open a shell on the server.");
258	        return;
259	      }
260	      // Shell is live — clear the auth/connect deadline.
261	      if (authTimer) {
262	        clearTimeout(authTimer);
263	        authTimer = null;
264	      }
265	      bump();
266	
267	      // Server → client: raw shell output.
268	      stream.on("data", (chunk: Buffer) => {
269	        bump();
270	        if (ws.readyState === WebSocket.OPEN) ws.send(chunk);
271	      });
272	      stream.stderr?.on("data", (chunk: Buffer) => {
273	        bump();
274	        if (ws.readyState === WebSocket.OPEN) ws.send(chunk);
275	      });
276	      stream.on("close", () => shutdown("shell closed"));
277	
278	      // Client → server: JSON control frames (keystrokes + resize).
279	      ws.on("message", (raw: Buffer, isBinary: boolean) => {
280	        bump();
281	        const msg = parseClientMsg(raw, isBinary);
282	        if (!msg) return;
283	        if (msg.type === "data") {
284	          stream.write(msg.data);
285	        } else if (msg.type === "resize") {
286	          try {
287	            stream.setWindow(msg.rows, msg.cols, 0, 0);
288	          } catch {
289	            /* ignore resize failures */
290	          }
291	        }
292	      });
293	    });
294	  });
295	
296	  ssh.on("error", () => {
297	    // Never surface SSH internals (or anything password-adjacent) to the client.
298	    shutdown("ssh error", "Could not connect to the server. Please try again.");
299	  });
300	  ssh.on("close", () => shutdown("ssh closed"));
301	
302	  try {
303	    ssh.connect({
304	      host: target.host,
305	      port: target.port,
306	      username: "root",
307	      password,
308	      readyTimeout: AUTH_CONNECT_TIMEOUT_MS,
309	      keepaliveInterval: 20_000,
310	    });
311	  } catch {
312	    shutdown("connect threw", "Could not connect to the server.");
313	  }
314	}
315	
316	/** Parse a client→server frame. Returns null for anything unrecognized. */
317	function parseClientMsg(raw: Buffer, isBinary: boolean): ClientMsg | null {
318	  if (isBinary) return null;
319	  let obj: unknown;
320	  try {
321	    obj = JSON.parse(raw.toString("utf8"));
322	  } catch {
323	    return null;
324	  }
325	  if (!obj || typeof obj !== "object") return null;
326	  const m = obj as Record<string, unknown>;
327	  if (m.type === "data" && typeof m.data === "string") {
328	    return { type: "data", data: m.data };
329	  }
330	  if (m.type === "resize") {
331	    return { type: "resize", cols: clampDim(m.cols, 80), rows: clampDim(m.rows, 24) };
332	  }
333	  return null;
334	}
335	
336	/**
337	 * Sandbox shell: a friendly simulated terminal. No SSH — just a banner and a
338	 * local echo of what the user types, so the whole UX works on staging.
339	 */
340	function startSandboxShell(
341	  ws: WebSocket,
342	  bump: () => void,
343	  shutdown: (reason: string, notify?: string) => void
344	): void {
345	  const nl = "\r\n";
346	  const prompt = "\x1b[32mnxeon-sandbox\x1b[0m:\x1b[34m~\x1b[0m# ";
347	  const banner =
348	    `\x1b[36mNxeon sandbox terminal\x1b[0m${nl}` +
349	    `This is a simulated shell on the staging environment — no real SSH` +
350	    ` connection is made.${nl}` +
351	    `Type anything and it will be echoed back. On production this is a real` +
352	    ` root shell where you can run \x1b[1mclaude\x1b[0m.${nl}${nl}`;
353	
354	  if (ws.readyState === WebSocket.OPEN) ws.send(banner + prompt);
355	
356	  let line = "";
357	  ws.on("message", (raw: Buffer, isBinary: boolean) => {
358	    bump();
359	    const msg = parseClientMsg(raw, isBinary);
360	    if (!msg || msg.type !== "data") return; // ignore resize in the sim
361	    for (const ch of msg.data) {
362	      if (ch === "\r" || ch === "\n") {
363	        let out = nl;
364	        if (line.trim()) out += `you typed: ${line}${nl}`;
365	        line = "";
366	        if (ws.readyState === WebSocket.OPEN) ws.send(out + prompt);
367	      } else if (ch === "\x7f" || ch === "\b") {
368	        if (line.length > 0) {
369	          line = line.slice(0, -1);
370	          if (ws.readyState === WebSocket.OPEN) ws.send("\b \b");
371	        }
372	      } else if (ch >= " ") {
373	        line += ch;
374	        if (ws.readyState === WebSocket.OPEN) ws.send(ch);
375	      }
376	    }
377	  });
378	
379	  // Keep the same guarantee that the socket eventually closes.
380	  void shutdown;
381	}
382	
