1	/**
2	 * Matrix "chat" console transport for the terminal-server.
3	 *
4	 * Runs the Claude Code CLI headless in stream-json mode over a NON-PTY SSH exec
5	 * channel on the customer's own server, and bridges its newline-delimited JSON
6	 * event stream to the browser (which parses it via lib/claude-stream and renders
7	 * a chat UI). The customer's own Claude login on the box is what authenticates —
8	 * this only shapes how it's invoked.
9	 *
10	 * The browser reaches this by opening the same authorized /terminal-ws socket
11	 * with `?mode=agent&approval=auto|ask`. See terminal-server/index.ts for the
12	 * (tiny) hooks that call into here.
13	 *
14	 * Frames — server → client:  {t:"ready"} | {t:"line",line} | {t:"notice",text} | {t:"exit",code}
15	 *          client → server:  {type:"prompt",text}
16	 */
17	import type { WebSocket } from "ws";
18	import type { Client as SshClient } from "ssh2";
19	
20	/** Longer idle window than a PTY: a chat build can run one silent tool for minutes. */
21	export const AGENT_IDLE_TIMEOUT_MS = 30 * 60_000;
22	
23	/** Max bytes of a single user prompt forwarded to the CLI's stdin. */
24	const MAX_PROMPT_LEN = 20_000;
25	
26	/** Parse the agent-mode flags off the websocket URL. */
27	export function parseAgentParams(reqUrl: string | undefined): {
28	  agentMode: boolean;
29	  approval: string;
30	} {
31	  try {
32	    const u = new URL(reqUrl ?? "/", "http://localhost");
33	    return {
34	      agentMode: u.searchParams.get("mode") === "agent",
35	      approval: u.searchParams.get("approval") || "ask",
36	    };
37	  } catch {
38	    return { agentMode: false, approval: "ask" };
39	  }
40	}
