42	/** Encode a user turn for `claude --input-format stream-json` (one NDJSON line). */
43	function encodeUserTurn(text: string): string {
44	  return JSON.stringify({ type: "user", message: { role: "user", content: text } });
45	}
46	
47	/**
48	 * The `claude` invocation for the chosen approval mode.
49	 *   - "auto": approve everything (Claude runs commands + edits on its own).
50	 *   - "ask" : run READ-ONLY (investigate + propose only, no changes) — a safe
51	 *             interim until the interactive per-action approval bridge is wired.
52	 * An explicit PATH is prepended because a non-interactive exec channel does not
53	 * source login profiles, so `claude` (symlinked to /usr/local/bin & ~/.local/bin
54	 * by the provisioner/backfill) would otherwise not be found.
55	 */
56	export function claudeAgentCmd(approval: string): string {
57	  const base =
58	    // IS_SANDBOX=1: the customer's VPS runs claude as root, and Claude Code
59	    // refuses bypassPermissions/--dangerously-skip-permissions as root ("cannot
60	    // be used with root/sudo privileges") UNLESS this flag marks the box as a
61	    // dedicated/sandboxed environment — which a customer's own server is.
62	    "PATH=/usr/local/bin:/root/.local/bin:$PATH IS_SANDBOX=1 " +
63	    "claude -p --output-format stream-json --input-format stream-json " +
64	    "--verbose --include-partial-messages ";
65	  if (approval === "auto") return base + "--permission-mode bypassPermissions";
66	  // "ask" interim = read-only preview until the interactive approval bridge lands.
67	  // allowedTools MUST be comma-separated — a space-separated value is parsed as one
68	  // invalid tool name, which allows NOTHING and leaves Claude stuck. Read-only tools
69	  // let it investigate + propose; writes/bash are denied, so it can't change anything.
70	  return base + '--permission-mode dontAsk --allowedTools "Read,Glob,Grep,LS,WebFetch,WebSearch"';
71	}
