73	type WsLike = WebSocket & { readyState: number };
74	const OPEN = 1; // WebSocket.OPEN
75	
76	/** Run claude headless over `ssh` and bridge its stream-json to `ws`. */
77	export function startAgentExec(
78	  ws: WsLike,
79	  ssh: SshClient,
80	  approval: string,
81	  bump: () => void,
82	  shutdown: (reason: string, notify?: string) => void
83	): void {
84	  ssh.exec(claudeAgentCmd(approval), { pty: false }, (err, stream) => {
85	    if (err) {
86	      shutdown("exec error", "Could not start Claude on the server.");
87	      return;
88	    }
89	    bump();
90	    const send = (o: unknown) => {
91	      if (ws.readyState === OPEN) ws.send(JSON.stringify(o));
92	    };
93	    send({ t: "ready" });
94	
95	    // stdout → NDJSON lines → client
96	    let buf = "";
97	    stream.on("data", (chunk: Buffer) => {
98	      bump();
99	      buf += chunk.toString("utf8");
100	      let nl: number;
101	      while ((nl = buf.indexOf("\n")) !== -1) {
102	        const line = buf.slice(0, nl);
103	        buf = buf.slice(nl + 1);
104	        if (line.trim()) send({ t: "line", line });
105	      }
106	    });
107	    stream.stderr?.on("data", (chunk: Buffer) => {
108	      bump();
109	      const text = chunk.toString("utf8").trim();
110	      if (text) send({ t: "notice", text: text.slice(0, 500) });
111	    });
112	    stream.on("close", (code: number | null) => {
113	      if (buf.trim()) send({ t: "line", line: buf });
114	      send({ t: "exit", code: code ?? 0 });
115	      shutdown("agent closed");
116	    });
117	
118	    // client → prompt → stdin
119	    ws.on("message", (raw: Buffer, isBinary: boolean) => {
120	      bump();
121	      if (isBinary) return;
122	      let msg: { type?: string; text?: string };
123	      try {
124	        msg = JSON.parse(raw.toString("utf8"));
125	      } catch {
126	        return;
127	      }
128	      if (msg.type === "prompt" && typeof msg.text === "string") {
129	        try {
130	          stream.write(encodeUserTurn(msg.text.slice(0, MAX_PROMPT_LEN)) + "\n");
131	        } catch {
132	          /* ignore */
133	        }
134	      }
135	    });
136	  });
137	}
