139	/** SANDBOX (staging): a simulated chat agent — no SSH, a few canned events. */
140	export function startSandboxAgent(
141	  ws: WsLike,
142	  bump: () => void,
143	  shutdown: (reason: string, notify?: string) => void
144	): void {
145	  const send = (o: unknown) => {
146	    if (ws.readyState === OPEN) ws.send(JSON.stringify(o));
147	  };
148	  const line = (o: unknown) => send({ t: "line", line: JSON.stringify(o) });
149	  send({ t: "ready" });
150	  line({ type: "system", subtype: "init", session_id: "sandbox", model: "claude (sandbox)", tools: ["Read", "Bash", "Edit"] });
151	  ws.on("message", (raw: Buffer, isBinary: boolean) => {
152	    bump();
153	    if (isBinary) return;
154	    let msg: { type?: string; text?: string };
155	    try {
156	      msg = JSON.parse(raw.toString("utf8"));
157	    } catch {
158	      return;
159	    }
160	    if (msg.type !== "prompt") return;
161	    line({ type: "assistant", content: [{ type: "text", text: `Sandbox: I'd work on "${String(msg.text).slice(0, 80)}" on your server here.` }] });
162	    line({ type: "assistant", content: [{ type: "tool_use", id: "t1", name: "Bash", input: { command: "echo hello" } }] });
163	    line({ type: "user", content: [{ type: "tool_result", tool_use_id: "t1", content: "hello" }] });
164	    line({ type: "result", is_error: false, result: "Done (sandbox).", num_turns: 1, duration_ms: 400 });
165	  });
166	  void shutdown;
167	}
